using System.Data.Common;

using Microsoft.EntityFrameworkCore.Diagnostics;

using H2Sharp.EntityFrameworkCore.TestUtilities;

#nullable enable

namespace H2Sharp.EntityFrameworkCore;

/// <summary>
/// The identity column: the DDL of it, and the statement that reads the value back.
/// </summary>
/// <remarks>
/// The two halves of the story are separate. The DDL is
/// <c>GENERATED BY DEFAULT AS IDENTITY</c>, and the engine reads it since the identity
/// columns were ported. The value the database made has to come back to the caller,
/// and H2 2.5 has no <c>RETURNING</c> for that: the row the insert made is read
/// through <c>FINAL TABLE</c>.
/// </remarks>
public class H2IdentityTests
{
    private readonly IServiceProvider _serviceProvider = new ServiceCollection()
        .AddEntityFrameworkH2()
        .BuildServiceProvider();

    [Fact]
    public void An_identity_value_comes_back_from_the_insert()
    {
        using var connection = new H2Connection("jdbc:h2:mem:IdentityValue");
        connection.Open();

        using var context = new ItemContext(_serviceProvider, connection);
        context.Database.EnsureDeleted();
        context.Database.EnsureCreated();

        var item = context.Add(new Item { Name = "x" }).Entity;
        context.SaveChanges();

        Assert.Equal(1, item.Id);
    }

    [Fact]
    public void The_insert_of_an_identity_row_is_written_the_way_H2_writes_it()
    {
        using var connection = new H2Connection("jdbc:h2:mem:IdentityStatement");
        connection.Open();

        SqlRecorder recorder = new();
        using var context = new ItemContext(_serviceProvider, connection, recorder);
        context.Database.EnsureDeleted();
        context.Database.EnsureCreated();

        context.Add(new Item { Name = "x" });
        _ = Record.Exception(() => context.SaveChanges());

        // The statement is what this test is about, and the recorder has it whether the
        // engine could run it or not. The parameter is named: the engine rewrites the
        // named parameters of a statement into the positional ones it reads.
        Assert.Equal(
            "SELECT \"Id\" FROM FINAL TABLE (INSERT INTO \"Items\" (\"Name\")\nVALUES (@p0));\n",
            recorder.Commands.Last().ReplaceLineEndings("\n"));
    }

    public void Dispose()
    {
        using var connection = new H2Connection("jdbc:h2:mem:IdentityValue");
        connection.Open();
        using var context = new ItemContext(_serviceProvider, connection);
        context.Database.EnsureDeleted();
    }

    /// <summary>
    /// Records the statements the provider sends, so that a test can say what the
    /// provider wrote without waiting for the engine to run it.
    /// </summary>
    private sealed class SqlRecorder : DbCommandInterceptor
    {
        public List<string> Commands { get; } = [];

        public override DbCommand CommandInitialized(CommandEndEventData eventData, DbCommand result)
        {
            Commands.Add(result.CommandText);
            return result;
        }
    }

    private class ItemContext(IServiceProvider serviceProvider, DbConnection connection, SqlRecorder? recorder = null)
        : DbContext
    {
        private readonly IServiceProvider _serviceProvider = serviceProvider;

        // ReSharper disable once UnusedAutoPropertyAccessor.Local
        public DbSet<Item> Items { get; set; }

        protected override void OnConfiguring(DbContextOptionsBuilder optionsBuilder)
        {
            optionsBuilder
                .UseH2(connection)
                .UseInternalServiceProvider(_serviceProvider);

            if (recorder is not null)
            {
                optionsBuilder.AddInterceptors(recorder);
            }
        }
    }

    private class Item
    {
        // ReSharper disable once UnusedAutoPropertyAccessor.Local
        public int Id { get; set; }

        // ReSharper disable once UnusedAutoPropertyAccessor.Local
        public string Name { get; set; } = string.Empty;
    }
}
